#!/bin/sh
# OpenCode Sidepanel installer. The bundle below is generated from dist/tui.js.
set -eu

CONFIG_HOME="${XDG_CONFIG_HOME:-$HOME/.config}"
OPENCODE_CONFIG="$CONFIG_HOME/opencode"
PLUGIN_DIR="$OPENCODE_CONFIG/plugins/opencode-sidepanel"
CLI_CONFIG="$OPENCODE_CONFIG/cli.json"

if ! command -v python3 >/dev/null 2>&1; then
  echo "OpenCode Sidepanel installer requires python3 to update cli.json." >&2
  exit 1
fi

mkdir -p "$PLUGIN_DIR/dist"
TMP_BUNDLE="$PLUGIN_DIR/dist/tui.js.tmp.$$"
cleanup() { rm -f "$TMP_BUNDLE"; }
trap cleanup EXIT HUP INT TERM

# macOS uses -D; GNU coreutils supports --decode.
if base64 --help 2>&1 | grep -q -- "--decode"; then
  awk '/^__SIDEPANEL_BUNDLE__$/ { bundle=1; next } bundle { print }' "$0" | base64 --decode > "$TMP_BUNDLE"
else
  awk '/^__SIDEPANEL_BUNDLE__$/ { bundle=1; next } bundle { print }' "$0" | base64 -D > "$TMP_BUNDLE"
fi
mv "$TMP_BUNDLE" "$PLUGIN_DIR/dist/tui.js"

cat > "$PLUGIN_DIR/package.json" <<'JSON'
{
  "name": "opencode-sidepanel",
  "version": "2.0.0",
  "private": true,
  "type": "module",
  "exports": {
    "./tui": "./dist/tui.js"
  }
}
JSON

python3 - "$CLI_CONFIG" "$PLUGIN_DIR" <<'PY'
import json
import os
import shutil
import sys
import tempfile
from pathlib import Path

config_path = Path(sys.argv[1])
plugin_path = str(Path(sys.argv[2]))
config_path.parent.mkdir(parents=True, exist_ok=True)
if config_path.exists():
    try:
        config = json.loads(config_path.read_text())
    except json.JSONDecodeError as error:
        raise SystemExit(f"Refusing to modify invalid JSON: {config_path}: {error}")
    backup = config_path.with_suffix(config_path.suffix + ".sidepanel-backup")
    shutil.copy2(config_path, backup)
else:
    config = {"$schema": "https://opencode.ai/v2/cli.json"}

plugins = config.get("plugins", [])
if not isinstance(plugins, list):
    raise SystemExit("Refusing to modify cli.json: plugins is not an array")
legacy_path = str(config_path.parent / "plugins" / "sidepanel")
plugins = [entry for entry in plugins if entry not in {plugin_path, legacy_path}]
plugins.append(plugin_path)
config["plugins"] = plugins

fd, name = tempfile.mkstemp(prefix="cli.", suffix=".json", dir=config_path.parent)
try:
    with os.fdopen(fd, "w") as handle:
        json.dump(config, handle, indent=2)
        handle.write("\n")
    os.replace(name, config_path)
finally:
    if os.path.exists(name):
        os.unlink(name)
PY

echo "OpenCode Sidepanel installed in: $PLUGIN_DIR"
echo "Restart OpenCode TUI windows to load it."
exit 0

__SIDEPANEL_BUNDLE__

